def observed(v):return (v.get('discovery') or {}).get('status')=='DISCOVERED'
def stable(v):return (v.get('groundState') or {}).get('value')=='STABLE'
def pretty(v):
 import re
 a,s=re.match(r'(\d+)([A-Za-z]+)',v['name']).groups();return s+'-'+a
def setstr(vs):return ', '.join(pretty(v) for v in sorted(vs,key=lambda q:(q['z'],q['n'])))
st60=setstr([v for v in chartEvidence if v['z']==60 and observed(v) and stable(v)])
rad60=setstr([v for v in chartEvidence if v['n']==60 and observed(v) and not stable(v)])
a60=setstr([v for v in chartEvidence if v['a']==60 and observed(v)])
R(90,[C('a · All stable observed Z60 nuclei',st60,st60+', Nd-144, Nd-150','Nd-144, Nd-150 only','NuDat labels Nd-142,143,145,146,148 STABLE; Nd-144 alpha and Nd-150 double-beta decay are observed.'),C('b · All radioactive observed N60 nuclei',rad60,rad60+', Ru-104, Pd-106, Ag-107, Cd-108','Ru-104, Pd-106, Ag-107, Cd-108 only','Select all22 discovered N60 isotones that are not stable. Ge-92 and As-93 were discovered in2024; absence of a measured half-life is not absence of discovery. Exclude the four stable isotones.'),C('c · All observed A60 nuclei',a60,a60+', As-60','Ni-60 only','All13 discovered entries from Ca-60 through Ge-60 are included, even where a half-life is not measured; As-60 has no discovery record.')],'The complete queried sets are derived from the official NNDC NuDat3 chart data snapshot; the version matters because isotope discovery and observed stability evolve.',scope='Official NNDC NuDat3 output.json snapshot reviewed2026-10-25; observed means discovery status DISCOVERED, including entries with unmeasured half-life. STABLE is the dataset classification, not a claim that every theoretically allowed decay is impossible.',ref='https://www.nndc.bnl.gov/nudat3/data/output.json')
