# Preserve math symbols and unit spellings while separating prose and numerical quantities.
import re
def clean(s):
 s=re.sub(r'(?<=[0-9])(?=[A-Za-z])',' ',s)
 s=re.sub(r'(?<=[a-z])(?=[0-9])',' ',s)
 s=re.sub(r'\b(Use|use|Set|set|Solve|solve|with|has|for|from|of|by|and|each|one|two|pure|initial|current|decayed|total|only|about|near|the|to|at|is|both|source)(?=[A-Z])',r'\1 ',s)
 s=s.replace('Initialrate','Initial rate').replace('Year=365.25days','Year=365.25 days')
 return s
for r in rows:
 for key in ['reasoning','scope','reviewNotice']:
  if key in r:r[key]=clean(r[key])
 r['assumptions']=[clean(a) for a in r['assumptions']]
 for p in r['parts']:
  p['noRounding']=r['id'].endswith(('problems-17','problems-91'))
  for key in ['label','explanation']:p[key]=clean(p[key])
next(r for r in rows if r['id'].endswith('problems-83'))['parts'][0]['acceptedValues']=[30.0]
assert len(rows)==112 and len({r['id'] for r in rows})==112
for r in rows:
 for p in r['parts']:
  if p['type']=='numeric':assert math.isfinite(p['answer']) and p['tolerance']>=0 and (not p['answer'] or p['tolerance']<abs(p['answer']))
  else:assert len(set(p['options']))==3 and p['answer'] in p['options']
